import {createGuide,recommendation,chooseTest,guideHint,nextQuestion} from './guided.mjs';
import {steps,comparisonValues,visibleDifferences,advancePair} from './comparison.mjs';
import {blocks,lessons} from './content.mjs';
import {createCase,frame,measure,diagnose,repair,verify,score,tests,faults,ignition} from './model.mjs';
import {mountBench} from './bench.mjs';
const $=s=>document.querySelector(s),key='mecanica.autos.v1';let saved={completed:[],results:[]},storageWarning='';try{const r=JSON.parse(localStorage.getItem(key)||'null');if(r){saved.completed=Array.isArray(r.completed)?r.completed.filter(id=>lessons.some(l=>l.id===id)):[];saved.results=Array.isArray(r.results)?r.results.filter(x=>x&&typeof x.id==='string'&&faults[x.fault]&&Number.isFinite(x.score)&&typeof x.date==='string').slice(-30):[];}}catch{storageWarning='No fue posible leer el progreso local.';}
let block=blocks[0].id,lesson=lessons[0],s,practice=false,playing=false,u=0,apart=false,cut=true,visible=false,last=0,raf=0,reference=null,healthy=null,healthyU=0,stepIndex=0,measurements={},guide=null;
const engine=mountBench($('#engineView'),'engine'),electric=mountBench($('#electricView'),'electric');
const parts={piston:['Pistón','Recibe presión de los gases y se desplaza dentro del cilindro.'],rod:['Biela','Une el bulón del pistón con la muñequilla del cigüeñal.'],crank:['Cigüeñal','Transforma el movimiento alternativo en giro.'],intake:['Admisión','Abre el camino de entrada de la carga.'],exhaust:['Escape','Permite la salida de los gases.'],spark:['Bujía','Inicia la combustión; no aporta la energía principal del motor.'],battery:['Batería','Entrega energía al arranque y estabiliza el sistema eléctrico.'],ground:['Masa','Retorno al negativo. La resistencia de conexión se manifiesta bajo carga.'],relay:['Solenoide','Recibe la orden y desplaza el piñón; habilita la potencia del arranque.'],starter:['Arranque','Convierte electricidad en giro inicial. El engrane con el volante no se dibuja en este banco separado.'],alternator:['Alternador','Aporta electricidad cuando lo mueve el motor. El corte deja ver rotor y bobinados.'],diodes:['Rectificador','Los diodos convierten la salida alterna en una salida rectificada.']};
function add(tag,text,host){const e=document.createElement(tag);e.textContent=text;host.append(e);return e;}
function button(text,host,fn){const b=add('button',text,host);b.onclick=fn;return b;}
function save(){try{localStorage.setItem(key,JSON.stringify(saved));storageWarning='';}catch{storageWarning='El almacenamiento no está disponible; el progreso permanece solo en esta sesión.';}$('#storageWarning').textContent=storageWarning;}
function selectPart(id){engine.select(id);electric.select(id);healthy?.select(id);$('#partInfo').textContent=parts[id]?parts[id].join(' · '):'';document.querySelectorAll('[data-part]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.part===id)));}
for(const [index,host]of [$('#engineParts'),$('#electricParts')].entries())for(const id of Object.keys(parts).slice(index?6:0,index?12:6)){const b=button(parts[id][0],host,()=>selectPart(id));b.dataset.part=id;}
function renderLesson(){document.title=lesson.title+' · Taller de carros';$('#lessonTitle').textContent=lesson.title;$('#lessonNumber').textContent=blocks.find(b=>b.id===block).name+' / '+(lessons.indexOf(lesson)+1)+' DE 18';for(const k of ['idea','body','observe','question'])$('#'+k).textContent=lesson[k];$('#answers').replaceChildren();$('#quizFeedback').textContent=saved.completed.includes(lesson.id)?'Lección aprobada. Puedes volver a practicar.':'';lesson.options.forEach((option,i)=>{const b=button(option,$('#answers'),()=>{const correct=i===lesson.answer;$('#quizFeedback').textContent=(correct?'Correcto. ':'Vuelve a intentarlo. ')+lesson.explanation;if(correct&&!saved.completed.includes(lesson.id)){saved.completed.push(lesson.id);save();renderNav();}});b.dataset.answer=i;});$('#nextLesson').disabled=lessons.indexOf(lesson)===lessons.length-1;selectPart(lesson.part);u=lesson.phase;healthyU=u;playing=false;$('#play').textContent='Reproducir 3D';refresh();}
function renderNav(){$('#blocks').replaceChildren();for(const [i,b]of blocks.entries()){const e=button('0'+(i+1)+' / '+b.name,$('#blocks'),()=>{block=b.id;lesson=lessons.find(l=>l.block===block);normal();renderLesson();});e.dataset.block=b.id;e.setAttribute('aria-pressed',String(block===b.id));}$('#lessons').replaceChildren();for(const l of lessons.filter(l=>l.block===block)){const e=button((saved.completed.includes(l.id)?'✓ ':'')+l.title,$('#lessons'),()=>{lesson=l;renderLesson();});e.dataset.lesson=l.id;e.setAttribute('aria-pressed',String(lesson.id===l.id));}$('#progress').textContent=saved.completed.length+'/18 lecciones aprobadas · '+saved.results.length+' casos verificados';}
function normal(){guide=null;s=createCase(block);s.fault=null;ignition(s,'crank');ignition(s,'run');reference={...s};healthyU=u;measurements={};stepIndex=0;practice=false;playing=false;$('#readings').replaceChildren();$('#feedback').textContent='Explora sin puntuación: motor sano en marcha, animación pausada. Pulsa Reproducir 3D o recorre el ciclo manualmente. Para probar el arranque, apaga y vuelve a intentarlo.';$('#solution').replaceChildren();refresh();}
function surprise(){guide=null;s=createCase(block);reference={...s,fault:null};healthyU=0;measurements={};stepIndex=0;practice=true;playing=false;u=0;$('#readings').replaceChildren();$('#feedback').textContent='Caso nuevo. Intenta arrancar, observa el síntoma y selecciona pruebas.';$('#solution').replaceChildren();refresh();}
function refresh(){const v=frame(s);$('#labMode').textContent=practice?'CASO SORPRESA · '+blocks.find(b=>b.id===block).name:'EXPLORACIÓN · SISTEMA SANO';$('#caseIntro').textContent=practice?'Una causa oculta. Mide sin penalización; hipótesis incorrecta o verificación incompleta: −10. Una pista: −10. Tras intervenir hay que repetir las pruebas.':'Aprende primero las lecturas sanas. Inicia un fallo sorpresa para diagnosticar y puntuar.';$('#score').textContent=practice?score(s)+'/100':'SIN NOTA';for(const id of ['confirm','repair','verify','hint'])$('#'+id).disabled=!practice||s.done||(id==='repair'&&(!s.diagnosed||s.repaired))||(id==='hint'&&s.hints>0)||(id==='confirm'&&s.repaired);$('#diagnosis').disabled=!practice||s.done||s.repaired;document.querySelectorAll('[data-key]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.key===s.key)));$('#play').setAttribute('aria-pressed',String(playing));$('#play').textContent=playing?'Pausar 3D':'Reproducir 3D';$('#status').textContent=v.status+(s.key==='run'&&!v.running?' · La llave volvió a marcha, pero no se sostiene el motor.':'');$('#cycle').disabled=apart;draw();renderNav();renderGuide();}
function draw(){if(!s)return;const v=frame(s);engine.draw(v,u);electric.draw(v,u);renderComparison(v);$('#angle').textContent=Math.round(u*720)+'°';$('#cycle').value=Math.floor(u*720);$('#phase').textContent=['Admisión · baja, entrada abierta','Compresión · sube, válvulas cerradas','Expansión · baja; solo hay combustión si se cumplen las condiciones','Escape · sube, salida abierta'][Math.min(3,Math.floor(u*4))]+(apart?' · despiece pausado':'');}
function tick(t){raf=0;const dt=last?Math.min((t-last)/1000,.05):0;last=t;if(playing&&!apart&&!document.hidden){const v=frame(s),pair=advancePair({actual:u,reference:healthyU},v,frame(reference),dt);u=pair.actual;healthyU=pair.reference;draw();}if(playing&&visible&&!document.hidden)raf=requestAnimationFrame(tick);}
function schedule(){if(!raf&&playing&&visible&&!document.hidden){last=0;raf=requestAnimationFrame(tick);}}
new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible)schedule();else if(raf){cancelAnimationFrame(raf);raf=0;}},{rootMargin:'100px'}).observe($('#lab'));
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(raf)cancelAnimationFrame(raf);raf=0;}else schedule();});matchMedia('(prefers-reduced-motion:reduce)').addEventListener('change',e=>{if(e.matches){playing=false;refresh();}});
function runMeasurement(id){playing=false;stepIndex=steps.findIndex(x=>x.id===id);const before=s.events.length,result=measure(s,id);measurements[id]=comparisonValues(s,reference,id);$('#feedback').textContent=result;if(s.events.length>before){add('li',(s.repaired?'Después de reparar · ':'')+tests[id]+': '+result,$('#readings'));while($('#readings').children.length>25)$('#readings').firstChild.remove();}selectPart(({battery:'battery',drop:'ground',command:'relay',spark:'spark',fuel:'intake',compression:'piston',charge:'alternator'})[id]);refresh();}
for(const [id,name]of Object.entries(tests)){const b=button(name,$('#tests'),()=>{if(guideLocked())return;runMeasurement(id);});b.dataset.test=id;}
for(const [id,f]of Object.entries(faults)){const o=add('option',f.name,$('#diagnosis'));o.value=id;}
$('#confirm').onclick=()=>{if(guideLocked())return;$('#feedback').textContent=diagnose(s,$('#diagnosis').value);refresh();};$('#hint').onclick=()=>{if(guideLocked())return;if(!practice||s.hints||s.done)return;s.hints=1;$('#feedback').textContent=faults[s.fault].hint;refresh();};$('#repair').onclick=()=>{if(guideLocked())return;$('#feedback').textContent=repair(s);ignition(reference,'off');healthyU=u;measurements={};playing=false;refresh();};$('#verify').onclick=()=>{if(guideLocked())return;if(verify(s)){$('#feedback').textContent='Caso verificado: arranque, prueba causal y carga correctos.';$('#solution').replaceChildren();add('h3',faults[s.fault].name,$('#solution'));add('p',faults[s.fault].why,$('#solution'));add('p','Antes: '+s.events.filter(e=>e.type==='test').slice(0,3).map(e=>e.result).join(' '),$('#solution'));if(!saved.results.some(r=>r.id===s.id)){saved.results.push({id:s.id,date:new Date().toISOString(),fault:s.fault,score:score(s),errors:s.errors,hints:s.hints});saved.results=saved.results.slice(-30);save();renderHistory();}}else $('#feedback').textContent='Falta verificar. Repara, repite la prueba causal durante Intentar arranque, pasa a Marcha, mide carga y vuelve a comprobar. −10 puntos.';refresh();};
$('#normal').onclick=normal;$('#surprise').onclick=surprise;document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{if(guideLocked())return;ignition(s,b.dataset.key);ignition(reference,b.dataset.key);refresh();schedule();});$('#play').onclick=()=>{if(apart||guide?.phase==='question')return;playing=!playing;refresh();schedule();};$('#cycle').oninput=e=>{if(guide?.phase==='question')return;playing=false;u=+e.target.value/720;healthyU=u;refresh();};$('#cut').onclick=()=>{cut=!cut;engine.cut(cut);electric.cut(cut);healthy?.cut(cut);$('#cut').setAttribute('aria-pressed',String(cut));$('#cut').textContent=cut?'Cerrar corte':'Abrir corte';};$('#explode').onclick=()=>{apart=!apart;playing=false;engine.explode(apart);electric.explode(apart);healthy?.explode(apart);$('#explode').setAttribute('aria-pressed',String(apart));$('#explode').textContent=apart?'Ensamblar':'Despiece';$('#play').disabled=apart;refresh();};$('#resetView').onclick=()=>{engine.reset();electric.reset();healthy?.reset();};$('#nextLesson').onclick=()=>{const next=lessons[lessons.indexOf(lesson)+1];if(!next)return;if(next.block!==block){block=next.block;normal();}lesson=next;renderLesson();$('#lesson').scrollIntoView({block:'start'});};
function renderComparison(actual){
 $('#caseStatus').hidden=!practice;$('#healthyCard').hidden=!practice;$('#comparisonPanel').hidden=!practice;$('#autoBanks').classList.toggle('comparing',practice);$('#engineLabel').textContent=practice?'B / MOTOR DEL CASO'+(s.repaired?' · REPARADO':''):'01 / MOTOR DE GASOLINA · UN CILINDRO';
 if(!practice){engine.highlight([]);return;}
 if(!healthy){healthy=mountBench($('#healthyView'),'engine');healthy.cut(cut);healthy.explode(apart);healthy.select(lesson.part);engine.onView?.(view=>healthy?.setView?.(view));healthy.onView?.(view=>engine.setView?.(view));healthy.setView?.(engine.getView?.());}
 const r=frame(reference),step=steps[stepIndex],measurement=measurements[step.id];healthy.draw(r,healthyU);
 const ids=visibleDifferences(actual,r);if(measurement?.valid&&measurement.different)ids.push(step.part);engine.highlight([...new Set(ids)]);
 $('#caseStatus').textContent=actual.status+' · '+actual.rpm+' rpm del modelo';$('#healthyStatus').textContent=r.status+' · '+r.rpm+' rpm del modelo';
 $('#pairStatus').textContent='A: '+r.rpm+' rpm · '+Math.round(healthyU*720)+'° / B: '+actual.rpm+' rpm · '+Math.round(u*720)+'°'+(s.repaired?' · después de reparar':'');
 $('#stepTitle').textContent=guide?.phase==='question'?'Prueba pendiente de tu elección':step.title;$('#stepWhy').textContent=guide?.phase==='question'?'Elige una medición en el modo guiado. Después compararemos las lecturas.':step.why;$('#stepPrev').disabled=guideLocked()||stepIndex===0;$('#stepNext').disabled=guideLocked()||stepIndex===steps.length-1;
 $('#referenceMeasurement').textContent=measurement?.reference||'Pendiente: pulsa Medir este paso.';$('#actualMeasurement').textContent=measurement?.actual||'Pendiente: pulsa Medir este paso.';
 $('#stepInterpretation').textContent=!measurement?'Compara las lecturas, no adivines una pieza. Las pruebas no restan puntos.':!measurement.valid?(step.id==='charge'?'La carga requiere ambos motores en marcha. Si B no se sostiene, vuelve a las pruebas de no-arranque; la falta de carga no es un diagnóstico válido aquí.':'Selecciona Intentar arranque. La compresión requiere además giro en ambos bancos.'):(measurement.different?'Las lecturas difieren: la región asociada queda señalada en ámbar. ':'Las lecturas coinciden en esta prueba; eso no descarta fallos en otros sistemas. ')+(step.id==='drop'&&!measurement.a.cranks?'Sin carga, el cero de B no prueba una masa sana. ':step.id==='spark'&&!measurement.a.cranks?'Sin giro, la falta de chispa no condena el encendido. ':'')+'Lectura capturada al medir; repite la prueba si cambias las condiciones. Los valores son del banco didáctico.';
}
function selectStep(index){if(guideLocked())return;stepIndex=index;playing=false;const st=steps[index];selectPart(st.part);electric.select(st.electric);refresh();}
$('#stepPrev').onclick=()=>selectStep(Math.max(0,stepIndex-1));$('#stepNext').onclick=()=>selectStep(Math.min(steps.length-1,stepIndex+1));$('#stepMeasure').onclick=()=>document.querySelector('[data-test="'+steps[stepIndex].id+'"]').click();
function guideLocked(){return !!guide&&guide.phase!=='complete';}
function renderGuide(){const active=guideLocked(),question=guide?.phase==='question';$('#guidedPanel').hidden=!guide;
 document.querySelectorAll('[data-test]').forEach(b=>b.disabled=active);document.querySelectorAll('[data-key]').forEach(b=>b.disabled=active);
 for(const id of ['stepPrev','stepNext','stepMeasure'])if(active)$('#'+id).disabled=true;
 if(active){for(const id of ['confirm','repair','verify','hint'])$('#'+id).disabled=true;$('#diagnosis').disabled=true;}
 $('#play').disabled=apart||question;$('#cycle').disabled=apart||question;
 if(!guide)return;
 $('#guidedTitle').textContent=guide.phase==='complete'?'Evidencia reunida · ahora diagnostica':question?'Paso '+guide.round+' · ¿qué medirías ahora?':'Paso '+guide.round+' · interpreta la comparación';
 $('#guidedPrompt').textContent='Caso: '+frame(s).status+' · '+score(s)+'/100. '+(question?'Bancos pausados. Elige una prueba antes de revelar su lectura. Se aceptan alternativas útiles; −10 por opción no prioritaria y −10 por pista.':guide.phase==='review'?'La prueba se realizó con ambos bancos en las mismas condiciones. Revisa sus lecturas abajo. Puedes reproducir el 3D y luego pasar a la siguiente decisión.':'Ya tienes evidencia para confirmar una causa. Elige el diagnóstico, aplica la reparación y repite las pruebas para verificar.');
 $('#guidedChoices').replaceChildren();if(question)for(const [id,name]of Object.entries(tests)){const b=button(name,$('#guidedChoices'),()=>{if(!chooseTest(s,guide,id)){refresh();return;}runMeasurement(id);renderGuide();});b.dataset.guideTest=id;}
 $('#guidedHint').disabled=!question||guide.hinted;$('#guidedNext').disabled=guide.phase!=='review';$('#guidedFeedback').textContent=guide.message+(guide.phase==='review'&&measurements[steps[stepIndex].id]?' A (sano): '+measurements[steps[stepIndex].id].reference+'. B (caso): '+measurements[steps[stepIndex].id].actual+'. '+steps[stepIndex].why:'');$('#guidedLog').replaceChildren();for(const event of guide.log)add('li','Paso '+event.round+' · '+tests[event.choice]+' · '+(event.correct?'elección útil':'no prioritaria'),$('#guidedLog'));
}
$('#guidedStart').onclick=()=>{surprise();guide=createGuide();ignition(s,'crank');ignition(reference,'crank');if(frame(s).starts){ignition(s,'run');ignition(reference,'run');}playing=false;u=healthyU=.375;selectPart('crank');refresh();$('#guidedPanel').scrollIntoView({block:'start'});};
$('#guidedHint').onclick=()=>{if(!guide)return;guideHint(s,guide);refresh();};
$('#guidedNext').onclick=()=>{if(!guide)return;playing=false;nextQuestion(s,guide);refresh();};
$('#guidedExit').onclick=()=>{guide=null;playing=false;refresh();};
function renderHistory(){$('#history').replaceChildren();if(!saved.results.length)add('li','Aún no hay casos verificados. Empieza por las lecturas sanas.', $('#history'));for(const r of saved.results.slice().reverse())add('li',new Date(r.date).toLocaleDateString('es-CO')+' · '+faults[r.fault].name+' · '+r.score+'/100 · '+r.errors+' errores · '+r.hints+' pistas',$('#history'));$('#storageWarning').textContent=storageWarning;}
normal();renderLesson();renderHistory();window.autoDebug=()=>({s,block,lesson:lesson.id,saved,frame:frame(s),engine:engine.debug?.(),electric:electric.debug?.(),u,playing,reference:frame(reference),healthy:healthy?.debug?.(),healthyU,stepIndex,measurements,guide});
